#include <string>
#include <vector>

// A fill counts every copy made of it.
struct Fill {
    std::string id;
    int qty;
    static int copies;
    Fill(std::string i, int q) : id(std::move(i)), qty(q) {}
    Fill(const Fill& o) : id(o.id), qty(o.qty) { ++copies; }
    Fill(Fill&& o) noexcept : id(std::move(o.id)), qty(o.qty) {}
    Fill& operator=(const Fill& o) { id = o.id; qty = o.qty; ++copies; return *this; }
    Fill& operator=(Fill&& o) noexcept { id = std::move(o.id); qty = o.qty; return *this; }
};
int Fill::copies = 0;

