// hidden test helpers
std::vector<Fill> make_fills(const std::string& tag, int n) {
    std::vector<Fill> v;
    for (int i = 0; i < n; ++i) v.emplace_back(tag + std::to_string(i), i + 1);
    return v;
}
// moves n fills tagged b onto m fills tagged a; returns copies made, sizes after, then every id
std::vector<std::string> run_take(int m, int n) {
    std::vector<Fill> dst = make_fills("a", m), src = make_fills("b", n);
    Fill::copies = 0;
    take_all(dst, std::move(src));
    std::vector<std::string> out{std::to_string(Fill::copies), std::to_string(dst.size()), std::to_string(src.size())};
    for (const Fill& f : dst) out.push_back(f.id + ":" + std::to_string(f.qty));
    return out;
}

